import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
// 1. Define the exact inline schema


export type ActionBurstTransitionProps = Record<string, any>;

// Pre-defined jagged paths mimicking comic/anime action lines
// Normalized to extend along the positive X-axis
const BOLT_PATHS = [
  // Path A: Classic thick jagged bolt
  "M 0,-30 L 40,-45 L 30,-15 L 90,-25 L 60,0 L 140,0 L 70,20 L 80,40 L 40,15 L 20,40 L 0,30 Z",
  // Path B: Long sharp spike with one main cut
  "M 0,-20 L 70,-30 L 50,-5 L 180,0 L 50,15 L 70,30 L 0,20 Z",
  // Path C: Complex multi-step zig-zag
  "M 0,-40 L 50,-50 L 30,-20 L 100,-10 L 80,10 L 150,20 L 70,40 L 90,60 L 30,30 L 0,40 Z",
];

const ActionBurstTransition: React.FC<ActionBurstTransitionProps> = ({
  backgroundColor = "#e6007e",
  boltColor = "#f570a5",
  transparentBackground = true,
  durationInSeconds = 2,
  boltCount = 18,
  focalPointX = 0.65,
  focalPointY = 0.5,
  rotationSpeed = 20,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Root container background logic
  const rootBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Calculate the maximum radius needed to cover the entire screen from any focal point
  const maxRadius = Math.sqrt(width * width + height * height) * 1.2;
  const cx = width * focalPointX;
  const cy = height * focalPointY;

  // -- Animation Timings & Physics --
  
  // 1. Entrance of the solid background (sweeps in quickly)
  const bgProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.6, stiffness: 150 },
  });

  // 2. Entrance of the jagged bolts (staggered slightly after background)
  const boltBaseProgress = spring({
    frame: frame - Math.floor(fps * 0.1),
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 120 },
  });

  // 3. Exit transition (punches a hole to reveal what's underneath)
  // Starts at 65% of the total duration
  const exitStartFrame = Math.floor(fps * durationInSeconds * 0.65);
  const exitProgress = spring({
    frame: frame - exitStartFrame,
    fps,
    config: { damping: 16, mass: 0.9, stiffness: 100 },
  });

  // Calculate dynamic radii
  const currentBgRadius = bgProgress * maxRadius;
  const currentHoleRadius = exitProgress * maxRadius;
  
  // Continuous slow rotation for the entire burst group
  const groupRotation = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, rotationSpeed]
  );

  // Generate deterministic randomized bolt data
  const bolts = useMemo(() => {
    const arr = [];
    for (let i = 0; i < boltCount; i++) {
      // Base angle + slight random jitter
      const angle = (i / boltCount) * Math.PI * 2 + (random(`ang-${i}`) * 0.15 - 0.075);
      // Randomize scale for depth/variation
      const scaleBase = 0.6 + random(`scale-${i}`) * 1.2;
      // Randomly select one of the path shapes
      const pathTypeIndex = Math.floor(random(`type-${i}`) * BOLT_PATHS.length);
      // Random stagger delay for entrance
      const staggerDelay = random(`delay-${i}`) * 5;
      
      arr.push({ 
        angle, 
        scaleBase, 
        d: BOLT_PATHS[pathTypeIndex],
        staggerDelay
      });
    }
    return arr;
  }, [boltCount]);

  return (
    <AbsoluteFill style={{ backgroundColor: rootBgColor, transition: "none" }}>
      <svg 
        width="100%" 
        height="100%" 
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: 'visible' }}
      >
        <defs>
          {/* Wipe mask: White reveals the transition graphics, Black hides them (creating the hole) */}
          <mask id="wipe-mask">
            <rect x={-width} y={-height} width={width * 3} height={height * 3} fill="white" />
            <circle cx={cx} cy={cy} r={currentHoleRadius} fill="black" />
          </mask>
        </defs>

        {/* Apply the mask to the entire transition graphic group */}
        <g mask="url(#wipe-mask)">
          
          {/* Layer 1: The solid magenta base that sweeps in */}
          <circle 
            cx={cx} 
            cy={cy} 
            r={currentBgRadius} 
            fill={backgroundColor} 
          />

          {/* Layer 2: The dynamic light pink bolts */}
          <g transform={`translate(${cx}, ${cy}) rotate(${groupRotation})`}>
            {bolts.map((bolt, i) => {
              // Individual spring for each bolt to create a staggered burst effect
              const individualProgress = spring({
                frame: frame - Math.floor(fps * 0.1) - bolt.staggerDelay,
                fps,
                config: { damping: 12, mass: 0.7, stiffness: 130 }
              });

              // Base path is ~150 units long. Scale it up relative to maxRadius to ensure it covers screen.
              // Math.max(0, ...) ensures we don't pass negative scales if spring bounces briefly below 0.
              const scaleFactor = Math.max(0, individualProgress * bolt.scaleBase * (maxRadius / 150));
              
              return (
                <g 
                  key={i} 
                  transform={`rotate(${(bolt.angle * 180) / Math.PI}) scale(${scaleFactor})`}
                >
                  <path 
                    d={bolt.d} 
                    fill={boltColor} 
                    style={{ transition: "none" }}
                  />
                </g>
              );
            })}
          </g>
          
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default ActionBurstTransition;